/* MedicCare.module.css — faithful port of Templatemo Medic Care */

.root {
  /* Spine roles derived from original palette */
  --vt-surface: #ffffff;
  --vt-surface-2: #f9f9f9;
  --vt-surface-deep: #000000;
  --vt-ink: #565758;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #247cff;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #ffffff;
  --vt-accent-on-deep: #ffffff;
  --vt-line: #eaeaea;

  /* Typography */
  --h1-size: 48px;
  --h2-size: 36px;
  --h3-size: 32px;
  --h4-size: 28px;
  --h5-size: 24px;
  --h6-size: 22px;
  --p-size: 18px;
  --menu-size: 16px;
  --fw-light: 300;
  --fw-normal: 400;
  --fw-semibold: 600;
  --fw-bold: 700;

  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.5;
}

/* Generic reset within root */
.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-surface-deep);
  line-height: 1.2;
  font-weight: var(--fw-semibold);
  margin: 0 0 0.5em 0;
}

.root h1,
.root h2 {
  font-weight: var(--fw-bold);
}

.root h1 { font-size: var(--h1-size); }
.root h2 { font-size: var(--h2-size); }
.root h3 { font-size: var(--h3-size); }
.root h4 { font-size: var(--h4-size); }
.root h5 { font-size: var(--h5-size); }
.root h6 { font-size: var(--h6-size); }

.root p {
  color: var(--vt-ink-soft);
  font-size: var(--p-size);
  font-weight: var(--fw-light);
  letter-spacing: 0.5px;
  margin: 0 0 1em 0;
}

.root a {
  color: var(--vt-ink);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Navigation */
.nav {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  position: sticky;
  top: 0;
  z-index: 1000;
  padding: 1.25rem 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 1rem;
}

.logo {
  display: inline-block;
}

.brand {
  /* brand component will receive this class */
  color: var(--vt-accent);
  font-size: var(--h5-size);
  font-weight: var(--fw-bold);
  text-align: center;
  margin: 0 2rem;
}

.brand strong {
  color: var(--vt-ink-soft);
  font-size: 12px;
  display: block;
  position: relative;
  bottom: 5px;
}

.navLinks {
  display: flex;
  gap: 2rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: var(--fw-semibold);
  font-size: var(--menu-size);
  padding: 0.5rem 0;
  position: relative;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-surface-deep);
}

.navLinks a:focus-visible {
  outline: none;
}

/* Hero section */
.hero {
  position: relative;
  overflow: hidden;
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  height: 580px;
}

.heroTrack::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  scroll-snap-align: start;
  flex: 0 0 100%;
  height: 100%;
  margin: 0;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  z-index: 2;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
}

.heroTitle {
  font-size: var(--h1-size);
  margin-bottom: 0.25em;
  color: var(--vt-surface-deep);
}

.heroWord {
  color: var(--vt-accent);
}

.heroIntro {
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: var(--fw-semibold);
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: color 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  text-align: center;
  transition: top 0.3s cubic-bezier(0.19, 1, 0.56, 1);
  display: flex;
  align-items: center;
  justify-content: center;
}

.customLink:hover::before,
.customLink:focus-visible::before {
  top: 0;
}

.customLink:hover,
.customLink:focus-visible {
  color: var(--vt-accent);
}

.contactPhone {
  font-weight: var(--fw-semibold);
  color: var(--vt-ink);
  margin: 0;
}

.contactPhone i {
  font-style: normal;
  margin-right: 0.25rem;
}

/* About section */
.about {
  padding: 7rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 1rem;
}

.aboutRow {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.aboutText {
  flex: 1;
}

.aboutImage {
  flex: 0 0 50%;
  max-width: 50%;
}

.aboutImage img {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 0.25rem;
}

/* Gallery */
.gallery {
  padding: 0;
}

.galleryRow {
  display: flex;
  margin: 0;
}

.galleryItem {
  flex: 0 0 50%;
  max-width: 50%;
}

.galleryItem img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Timeline / Services */
.timelineSection {
  padding: 7rem 0 0;
}

.sectionTitle {
  text-align: center;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 0;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin: 2rem 0;
  position: relative;
}

.timelineNodeEven {
  flex-direction: row;
}

.timelineNodeOdd {
  flex-direction: row-reverse;
}

.timelineContent {
  width: 40%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  z-index: 1;
}

.timelineNodeEven .timelineContent {
  order: 1;
}

.timelineNodeOdd .timelineContent {
  order: 3;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  font-size: var(--h5-size);
}

.timelineNodeEven .timelineContent h3 {
  text-align: left;
}

.timelineNodeOdd .timelineContent h3 {
  text-align: right;
}

.timelineNodeEven .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
  border-right: 10px solid var(--vt-surface-deep);
}

.timelineNodeOdd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
  border-left: 10px solid var(--vt-surface-deep);
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
}

.timelineNodeEven .timelineContent p {
  text-align: left;
}

.timelineNodeOdd .timelineContent p {
  text-align: right;
}

.timelineIconWrapper {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  order: 2;
  margin: 0 1rem;
}

.timelineIcon {
  display: block;
  width: 40px;
  height: 40px;
  background: var(--vt-accent);
  border-radius: 50%;
}

.timelineDate {
  width: 40%;
  padding: 1rem 0;
}

.timelineNodeEven .timelineDate {
  order: 3;
  text-align: right;
}

.timelineNodeOdd .timelineDate {
  order: 1;
  text-align: left;
}

.timelineDate time {
  color: var(--vt-ink-soft);
  font-size: var(--menu-size);
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1 1 30%;
  min-width: 250px;
}

.footerCol h5 {
  margin-bottom: 1rem;
  color: var(--vt-surface-deep);
}

.hours {
  white-space: pre-line;
  color: var(--vt-ink-soft);
}

.footerCopy {
  width: 100%;
  margin-top: 2rem;
}

.copyright {
  font-size: var(--menu-size);
  margin: 0;
}

/* Responsive adjustments */
@media screen and (max-width: 991px) {
  .root {
    --h1-size: 38px;
    --h2-size: 32px;
    --h3-size: 26px;
    --h4-size: 24px;
    --h5-size: 20px;
    --h6-size: 18px;
  }

  .nav {
    padding: 0.75rem 0;
  }

  .heroTrack {
    height: 500px;
  }

  .heroText {
    position: static;
    width: auto;
    background: var(--vt-surface);
    margin-bottom: -100px;
    padding: 2rem;
  }

  .aboutRow {
    flex-direction: column;
    align-items: stretch;
  }

  .aboutImage {
    flex: 0 0 100%;
    max-width: 100%;
  }

  .timeline::before {
    left: 33px;
    height: 90%;
    top: 60px;
  }

  .timelineNode,
  .timelineNodeEven,
  .timelineNodeOdd {
    flex-direction: column;
    align-items: flex-start;
    padding-left: 80px;
  }

  .timelineIconWrapper {
    position: absolute;
    left: 0;
    top: 60px;
    width: 70px;
    height: 70px;
    margin: 0;
  }

  .timelineContent {
    width: 100%;
  }

  .timelineDate {
    width: 100%;
    text-align: left;
    padding-left: 80px;
  }

  .timelineNodeEven .timelineContent h3::after,
  .timelineNodeOdd .timelineContent h3::after {
    right: 100%;
    left: auto;
    border-right: 10px solid var(--vt-surface-deep);
    border-left: 0;
  }

  .timelineNodeEven .timelineContent h3,
  .timelineNodeOdd .timelineContent h3 {
    text-align: left;
  }

  .timelineNodeEven .timelineContent p,
  .timelineNodeOdd .timelineContent p {
    text-align: left;
  }
}

@media screen and (max-width: 575px) {
  .heroTrack {
    height: 400px;
  }

  .heroText {
    padding: 1.5rem;
  }

  .timeline::before {
    left: 20px;
  }

  .timelineIconWrapper {
    width: 60px;
    height: 60px;
  }

  .timelineIcon {
    width: 30px;
    height: 30px;
  }

  .galleryItem {
    flex: 0 0 100%;
    max-width: 100%;
  }

  .footerRow {
    flex-direction: column;
  }
}

@media screen and (max-width: 360px) {
  .root {
    --h1-size: 32px;
    --h2-size: 28px;
    --h3-size: 24px;
    --h4-size: 22px;
    --h5-size: 20px;
    --h6-size: 18px;
  }

  .heroTrack {
    height: 320px;
  }
}
